{
 "didatica": [
  {
   "campo": "resolucao.antes.texto",
   "depois": "Densidade demográfica é habitantes divididos por área. O enunciado não dá números, então use letras: h para os habitantes de R e A para a área de R. Escreva os dados de Q em função de h e A e divida. No fim, compare d(Q) com d(R).",
   "motivo": "Frases mais curtas e verbos no mesmo tempo."
  },
  {
   "campo": "resolucao.antes.formulas",
   "depois": [
    "densidade = habitantes ÷ área",
    "dividir por uma fração = multiplicar pelo inverso dela (o inverso de 4/3 é 3/4)"
   ],
   "motivo": "Explica o que é 'inverso' com um exemplo."
  },
  {
   "campo": "resolucao.passos[3].conta",
   "depois": "d(Q) = (h/2) ÷ (3A/4)",
   "motivo": "Sem mudança de conteúdo; mantida."
  },
  {
   "campo": "resolucao.passos[3].porque",
   "depois": "É a mesma definição, agora com os dados de Q. Dividir por 3A/4 é multiplicar pelo inverso, 4/(3A).",
   "motivo": "Frase mais clara."
  },
  {
   "campo": "resolucao.passos[4]",
   "depois": {
    "faz": "Simplifique e compare com d(R)",
    "conta": "d(Q) = 4h/(6A) = (2/3) × h/A",
    "porque": "4/6 simplifica para 2/3 e sobra h/A, que é d(R). Logo d(Q) = (2/3) d(R): alternativa E.",
    "tipo": "concluir"
   },
   "motivo": "O último passo agora liga o resultado à letra."
  },
  {
   "campo": "resolucao.erradas.A",
   "depois": "1/4 sai de subtrair as frações: 3/4 − 1/2 = 1/4. Densidade é uma divisão, não uma subtração: (1/2) ÷ (3/4) = 2/3. No teste com 100 hab. e 100 km², d(Q) = 50/75 = 2/3, e não 0,25.",
   "motivo": "Frases mais curtas."
  },
  {
   "campo": "resolucao.quadro[3].nota",
   "depois": "multiplique numerador por numerador e denominador por denominador",
   "motivo": "Mais claro para o aluno."
  }
 ],
